sys_script.condition:
(function() {
    // Only trigger when a clone is about to start (state = 'ready' or 'in_progress')
    var state = current.getValue('state') || '';
    return state === 'ready' || state === 'in_progress';
})();

sys_script.script:
// ConfigSync Pre-Clone Gate
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function executeRule(current, previous /*null when async*/) {
    try {
        var engine = new x_csync.ConfigSyncEngine();
        var instanceName = gs.getProperty('instance_name', '');
        var now = new GlideDateTime();
        var snapshotName = 'Pre-Clone ' + now.getDate().getByFormat('yyyy-MM-dd HH:mm');

        // Create a pre-clone snapshot
        var snapId = engine.fingerprintInstance(instanceName, snapshotName, 'pre_clone');
        if (!snapId) {
            gs.error('ConfigSync Pre-Clone Gate: Failed to create pre-clone snapshot');
            return;
        }

        // Find the most recent baseline snapshot (not this one)
        var baseline = new GlideRecord('x_csync_snapshot');
        baseline.addQuery('sys_id', '!=', snapId);
        baseline.addQuery('snapshot_type', '!=', 'pre_clone');
        baseline.orderByDesc('sys_created_on');
        baseline.setLimit(1);
        baseline.query();

        if (!baseline.next()) {
            gs.warn('ConfigSync Pre-Clone Gate: No baseline snapshot found for comparison. Skipping gate check.');
            return;
        }

        var gateReport = engine.checkGate(baseline.getUniqueValue(), snapId);

        if (gateReport.gate === 'FAIL') {
            gs.error('ConfigSync Pre-Clone Gate: CRITICAL — Drift score ' + gateReport.drift_score +
                     '/100. ' + gateReport.risk_items.length + ' high-risk items detected. ' +
                     'Clone may introduce configuration inconsistencies.');
        } else if (gateReport.gate === 'WARN') {
            gs.warn('ConfigSync Pre-Clone Gate: WARNING — Drift score ' + gateReport.drift_score +
                    '/100. ' + gateReport.risk_items.length + ' high-risk items. Review before proceeding.');
        } else {
            gs.info('ConfigSync Pre-Clone Gate: PASS — Drift score ' + gateReport.drift_score +
                    '/100. No high-risk items. Safe to clone.');
        }
    } catch (e) {
        gs.error('ConfigSync Pre-Clone Gate failed: ' + e.message);
    }
})(current, previous);

sys_trigger.script:
// ConfigSync Daily Scan
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function() {
    try {
        var engine = new x_csync.ConfigSyncEngine();
        var instanceName = gs.getProperty('instance_name', '');
        var now = new GlideDateTime();
        var snapshotName = 'Daily Scan ' + now.getDate().getByFormat('yyyy-MM-dd');

        var snapId = engine.fingerprintInstance(instanceName, snapshotName, 'scheduled');
        if (!snapId) {
            gs.error('ConfigSync Daily Scan: fingerprintInstance returned empty sys_id');
            return;
        }

        // Compare against the previous snapshot
        var prevSnap = new GlideRecord('x_csync_snapshot');
        prevSnap.addQuery('sys_id', '!=', snapId);
        prevSnap.orderByDesc('sys_created_on');
        prevSnap.setLimit(1);
        prevSnap.query();

        if (prevSnap.next()) {
            var report = engine.compareSnapshots(prevSnap.getUniqueValue(), snapId);
            gs.info('ConfigSync Daily Scan: Drift Score=' + report.drift_score +
                    ', Gate=' + report.gate + ', Items=' + report.drift_count);
        } else {
            gs.info('ConfigSync Daily Scan: First snapshot created (no previous to compare). ID=' + snapId);
        }
    } catch (e) {
        gs.error('ConfigSync Daily Scan failed: ' + e.message);
    }
})();

sys_script_include.script:
// ConfigSync — Instance Configuration Drift Auditor
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
//
// AI-powered drift analysis using Now Assist and GenAI Controller.
// @class ConfigSyncAI @namespace x_csync

var ConfigSyncAI = Class.create();
ConfigSyncAI.prototype = {
    initialize: function() {
        this.AI_ENABLED_PROP = 'x_csync.ai.enabled';
        this.AI_CACHE_TTL_DAYS = 7;
    },

    analyzeImpact: function(driftItemId) {
        if (!this._isAIEnabled()) {
            return '';
        }

        try {
            var di = new GlideRecord('x_csync_drift_item');
            if (!di.get(driftItemId)) {
                return '';
            }

            var existingAnalysis = di.getValue('ai_analysis') || '';
            if (existingAnalysis && this._isCacheFresh(di)) {
                return existingAnalysis;
            }

            var prompt = this._buildImpactPrompt(di);
            var analysis = this._callNowAssist(prompt);

            if (analysis) {
                di.setValue('ai_analysis', analysis);
                di.setWorkflow(false);
                di.update();
            }

            return analysis || '';
        } catch (e) {
            gs.error('ConfigSyncAI.analyzeImpact failed: ' + e.message);
            return '';
        }
    },

    suggestRemediation: function(driftItemId) {
        var result = { action: 'none', description: '', risk_level: 'unknown' };

        if (!this._isAIEnabled()) {
            result.description = 'AI analysis is disabled. Enable via x_csync.ai.enabled system property.';
            return result;
        }

        try {
            var di = new GlideRecord('x_csync_drift_item');
            if (!di.get(driftItemId)) {
                result.description = 'Drift item not found.';
                return result;
            }

            var prompt = this._buildRemediationPrompt(di);
            var suggestion = this._callNowAssist(prompt);

            if (suggestion) {
                result = this._parseRemediationResponse(suggestion);
            }
            return result;
        } catch (e) {
            gs.error('ConfigSyncAI.suggestRemediation failed: ' + e.message);
            return result;
        }
    },

    generateSummary: function(driftReport) {
        if (!this._isAIEnabled()) {
            return 'Drift Score: ' + (driftReport.drift_score || 0) +
                   '. Gate: ' + (driftReport.gate || 'UNKNOWN') +
                   '. Items: ' + (driftReport.drift_count || 0) + '.';
        }

        try {
            var prompt = 'Summarize this ServiceNow configuration drift report in 2-3 sentences for a platform administrator:\n' +
                         'Drift Score: ' + (driftReport.drift_score || 0) + '/100\n' +
                         'Gate: ' + (driftReport.gate || 'UNKNOWN') + '\n' +
                         'Total Artifacts: ' + (driftReport.total_artifacts || 0) + '\n' +
                         'Drift Items: ' + (driftReport.drift_count || 0) + '\n' +
                         'High-Risk Items: ' + this._countHighRisk(driftReport.items) + '\n\n' +
                         'Top drift items by risk:\n' + this._formatTopItems(driftReport.items, 5);

            return this._callNowAssist(prompt) || this._fallbackSummary(driftReport);
        } catch (e) {
            gs.error('ConfigSyncAI.generateSummary failed: ' + e.message);
            return this._fallbackSummary(driftReport);
        }
    },

    _isAIEnabled: function() {
        var prop = gs.getProperty(this.AI_ENABLED_PROP, 'true');
        return prop === 'true';
    },

    _isCacheFresh: function(driftItemGr) {
        var updated = driftItemGr.getValue('sys_updated_on');
        if (!updated) return false;
        var updatedGdt = new GlideDateTime(updated);
        var cutoff = new GlideDateTime();
        cutoff.addDays(-1 * this.AI_CACHE_TTL_DAYS);
        return updatedGdt.after(cutoff);
    },

    _buildImpactPrompt: function(driftItemGr) {
        var artifactType = driftItemGr.getValue('artifact_type') || 'unknown';
        var artifactName = driftItemGr.getValue('artifact_name') || 'unknown';
        var changeType = driftItemGr.getValue('change_type') || 'unknown';
        var diffSummary = driftItemGr.getValue('diff_summary') || '{}';

        return 'You are a ServiceNow platform architect. Analyze the impact of this configuration drift:\n' +
               'Artifact Type: ' + artifactType + '\n' +
               'Artifact Name: ' + artifactName + '\n' +
               'Change Type: ' + changeType + '\n' +
               'Diff: ' + diffSummary + '\n\n' +
               'Explain in 2-3 sentences what could break, which modules are affected, and the blast radius. ' +
               'Be specific about ServiceNow platform components.';
    },

    _buildRemediationPrompt: function(driftItemGr) {
        var artifactType = driftItemGr.getValue('artifact_type') || 'unknown';
        var artifactName = driftItemGr.getValue('artifact_name') || 'unknown';
        var changeType = driftItemGr.getValue('change_type') || 'unknown';
        var riskScore = driftItemGr.getValue('risk_score') || '0';

        return 'You are a ServiceNow platform architect. Suggest a remediation action for this drift:\n' +
               'Artifact Type: ' + artifactType + '\n' +
               'Artifact Name: ' + artifactName + '\n' +
               'Change Type: ' + changeType + '\n' +
               'Risk Score: ' + riskScore + '/100\n\n' +
               'Respond with exactly one line in this format:\n' +
               'ACTION: <promote|revert|review|ignore>\n' +
               'DESCRIPTION: <one sentence explaining the action>\n' +
               'RISK: <low|medium|high>';
    },

    _callNowAssist: function(prompt) {
        try {
            var genAI = new sn_generative_ai.GlideGenerativeAI();
            var response = genAI.generate(prompt, { max_tokens: 500, temperature: 0.3 });
            return response || '';
        } catch (e) {
            try {
                var nowAssist = new sn_now_assist.NowAssistAPI();
                var result = nowAssist.generateText(prompt, { maxTokens: 500 });
                return result || '';
            } catch (e2) {
                gs.warn('ConfigSyncAI: Both GenAI Controller and Now Assist unavailable. ' + e2.message);
                return '';
            }
        }
    },

    _parseRemediationResponse: function(response) {
        var result = { action: 'review', description: response, risk_level: 'medium' };
        var lines = response.split('\n');
        for (var i = 0; i < lines.length; i++) {
            var line = lines[i].trim();
            if (line.indexOf('ACTION:') === 0) {
                var action = line.substring(7).trim().toLowerCase();
                if (action === 'promote' || action === 'revert' || action === 'review' || action === 'ignore') {
                    result.action = action;
                }
            } else if (line.indexOf('DESCRIPTION:') === 0) {
                result.description = line.substring(12).trim();
            } else if (line.indexOf('RISK:') === 0) {
                var risk = line.substring(5).trim().toLowerCase();
                if (risk === 'low' || risk === 'medium' || risk === 'high') {
                    result.risk_level = risk;
                }
            }
        }
        return result;
    },

    _countHighRisk: function(items) {
        if (!items) return 0;
        var count = 0;
        for (var i = 0; i < items.length; i++) {
            if (items[i].risk_score >= 70) count++;
        }
        return count;
    },

    _formatTopItems: function(items, limit) {
        if (!items || items.length === 0) return '(none)';
        var sorted = items.slice().sort(function(a, b) { return b.risk_score - a.risk_score; });
        var result = '';
        var max = Math.min(sorted.length, limit || 5);
        for (var i = 0; i < max; i++) {
            result += '- [' + sorted[i].risk_score + '/100] ' + sorted[i].artifact_type + ' :: ' + sorted[i].artifact_name + ' (' + sorted[i].change_type + ')\n';
        }
        return result;
    },

    _fallbackSummary: function(driftReport) {
        return 'Drift Score: ' + (driftReport.drift_score || 0) + '/100. ' +
               'Gate: ' + (driftReport.gate || 'UNKNOWN') + '. ' +
               (driftReport.drift_count || 0) + ' drift items detected out of ' +
               (driftReport.total_artifacts || 0) + ' total artifacts.';
    },

    type: 'ConfigSyncAI'
};

// ConfigSync — Instance Configuration Drift Auditor
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
//
// Core engine for configuration fingerprinting, comparison, and risk scoring.
// @class ConfigSyncEngine @namespace x_csync

var ConfigSyncEngine = Class.create();
ConfigSyncEngine.prototype = {
    initialize: function() {
        this.ARTIFACT_TYPES = [
            { table: 'sys_properties',     field: 'value',  nameField: 'name',  riskWeight: 0.4, label: 'sys_properties' },
            { table: 'sys_script',          field: 'script', nameField: 'name',  riskWeight: 0.8, label: 'sys_script' },
            { table: 'sys_security_acl',    field: 'script', nameField: 'name',  riskWeight: 0.9, label: 'sys_security_acl' },
            { table: 'sys_script_client',   field: 'script', nameField: 'name',  riskWeight: 0.5, label: 'sys_script_client' },
            { table: 'sys_ui_policy',       field: 'script_true', nameField: 'name', riskWeight: 0.5, label: 'sys_ui_policy' },
            { table: 'sys_dictionary',      field: 'default_value', nameField: 'element', riskWeight: 0.6, label: 'sys_dictionary' },
            { table: 'sys_trigger',         field: 'script', nameField: 'name',  riskWeight: 0.7, label: 'sys_trigger' },
            { table: 'sys_script_include',  field: 'script', nameField: 'name',  riskWeight: 0.7, label: 'sys_script_include' }
        ];
    },

    fingerprintInstance: function(instanceName, snapshotName, snapshotType) {
        try {
            var artifacts = [];
            for (var i = 0; i < this.ARTIFACT_TYPES.length; i++) {
                var at = this.ARTIFACT_TYPES[i];
                var gr = new GlideRecord(at.table);
                gr.addQuery('sys_scope', 'global');
                gr.setLimit(500);
                gr.query();
                while (gr.next()) {
                    var payload = this._normalizePayload(gr, at);
                    var hash = this._sha256(payload);
                    artifacts.push({
                        type: at.label,
                        name: gr.getValue(at.nameField) || '',
                        sys_id: gr.getUniqueValue() || '',
                        hash: hash,
                        fields_summary: this._summarizeFields(gr, at)
                    });
                }
            }

            var snap = new GlideRecord('x_csync_snapshot');
            snap.initialize();
            snap.setValue('name', snapshotName);
            snap.setValue('instance', instanceName);
            snap.setValue('snapshot_type', snapshotType);
            snap.setValue('artifact_count', artifacts.length);
            snap.setValue('artifacts_json', JSON.stringify(artifacts));
            var snapId = snap.insert();
            return snapId || '';
        } catch (e) {
            gs.error('ConfigSyncEngine.fingerprintInstance failed: ' + e.message);
            return '';
        }
    },

    compareSnapshots: function(baselineId, targetId) {
        var report = { drift_score: 100, items: [], gate: 'PASS', total_artifacts: 0, drift_count: 0 };

        try {
            var baseline = this._loadSnapshot(baselineId);
            var target = this._loadSnapshot(targetId);
            if (!baseline || !target) {
                report.gate = 'FAIL';
                report.drift_score = 0;
                return report;
            }

            var baselineMap = this._buildArtifactMap(baseline.artifacts);
            var targetMap = this._buildArtifactMap(target.artifacts);
            report.total_artifacts = baseline.artifacts.length;

            for (var key in baselineMap) {
                if (!baselineMap.hasOwnProperty(key)) continue;
                if (!targetMap[key]) {
                    var item = this._createDriftItem(baselineMap[key], null, 'removed', baselineId, targetId);
                    report.items.push(item);
                }
            }

            for (var tKey in targetMap) {
                if (!targetMap.hasOwnProperty(tKey)) continue;
                if (!baselineMap[tKey]) {
                    var addedItem = this._createDriftItem(null, targetMap[tKey], 'added', baselineId, targetId);
                    report.items.push(addedItem);
                } else if (baselineMap[tKey].hash !== targetMap[tKey].hash) {
                    var modItem = this._createDriftItem(baselineMap[tKey], targetMap[tKey], 'modified', baselineId, targetId);
                    report.items.push(modItem);
                }
            }

            report.drift_count = report.items.length;

            if (report.items.length > 0) {
                var totalRisk = 0;
                for (var j = 0; j < report.items.length; j++) {
                    totalRisk += report.items[j].risk_score;
                }
                var avgRisk = totalRisk / report.items.length;
                report.drift_score = Math.max(0, Math.round(100 - avgRisk));
            }

            if (report.drift_score < 50) {
                report.gate = 'FAIL';
            } else if (report.drift_score < 80) {
                report.gate = 'WARN';
            } else {
                report.gate = 'PASS';
            }

            for (var k = 0; k < report.items.length; k++) {
                this._saveDriftItem(report.items[k]);
            }

            return report;
        } catch (e) {
            gs.error('ConfigSyncEngine.compareSnapshots failed: ' + e.message);
            report.gate = 'FAIL';
            report.drift_score = 0;
            return report;
        }
    },

    calculateRiskScore: function(driftItem) {
        var baseWeight = 0.5;
        for (var i = 0; i < this.ARTIFACT_TYPES.length; i++) {
            if (this.ARTIFACT_TYPES[i].label === driftItem.artifact_type) {
                baseWeight = this.ARTIFACT_TYPES[i].riskWeight;
                break;
            }
        }

        var changeMultiplier = 1.0;
        if (driftItem.change_type === 'removed') {
            changeMultiplier = 1.2;
        } else if (driftItem.change_type === 'added') {
            changeMultiplier = 0.8;
        }

        return Math.min(100, Math.round(baseWeight * changeMultiplier * 100));
    },

    generateDiff: function(artifactA, artifactB) {
        var result = { type: 'identical', fields_diff: {}, summary: '' };
        if (!artifactA && artifactB) {
            result.type = 'added';
            result.summary = 'New artifact: ' + (artifactB.name || 'unknown');
            return result;
        }
        if (artifactA && !artifactB) {
            result.type = 'removed';
            result.summary = 'Removed artifact: ' + (artifactA.name || 'unknown');
            return result;
        }
        if (!artifactA || !artifactB) {
            return result;
        }

        var diffFields = {};
        var allKeys = {};
        for (var k in artifactA.fields_summary) {
            if (artifactA.fields_summary.hasOwnProperty(k)) allKeys[k] = true;
        }
        for (var k2 in artifactB.fields_summary) {
            if (artifactB.fields_summary.hasOwnProperty(k2)) allKeys[k2] = true;
        }

        var hasDiff = false;
        for (var key in allKeys) {
            if (!allKeys.hasOwnProperty(key)) continue;
            var valA = artifactA.fields_summary[key] || '';
            var valB = artifactB.fields_summary[key] || '';
            if (valA !== valB) {
                diffFields[key] = { before: valA, after: valB };
                hasDiff = true;
            }
        }

        if (hasDiff) {
            result.type = 'modified';
            result.fields_diff = diffFields;
            var changedFields = [];
            for (var fk in diffFields) {
                if (diffFields.hasOwnProperty(fk)) changedFields.push(fk);
            }
            result.summary = 'Changed fields: ' + changedFields.join(', ');
        }

        return result;
    },

    getDriftTimeline: function(instanceName, days) {
        var timeline = { points: [] };
        try {
            var cutoff = new GlideDateTime();
            cutoff.addDays(-1 * (days || 30));

            var snap = new GlideRecord('x_csync_snapshot');
            snap.addQuery('instance', instanceName);
            snap.addQuery('sys_created_on', '>=', cutoff);
            snap.orderBy('sys_created_on');
            snap.query();

            while (snap.next()) {
                var driftCount = this._countDriftItems(snap.getUniqueValue());
                timeline.points.push({
                    snapshot_id: snap.getUniqueValue(),
                    name: snap.getValue('name') || '',
                    created_at: snap.getValue('sys_created_on') || '',
                    artifact_count: parseInt(snap.getValue('artifact_count') || '0', 10),
                    drift_count: driftCount
                });
            }
            return timeline;
        } catch (e) {
            gs.error('ConfigSyncEngine.getDriftTimeline failed: ' + e.message);
            return timeline;
        }
    },

    checkGate: function(baselineId, targetId) {
        var report = this.compareSnapshots(baselineId, targetId);
        var highRiskItems = [];
        for (var i = 0; i < report.items.length; i++) {
            if (report.items[i].risk_score >= 70) {
                highRiskItems.push(report.items[i]);
            }
        }
        return {
            drift_score: report.drift_score,
            gate: report.gate,
            risk_items: highRiskItems,
            deployable: report.gate === 'PASS',
            total_drift: report.drift_count,
            total_artifacts: report.total_artifacts
        };
    },

    _normalizePayload: function(gr, artifactType) {
        var fields = {};
        var keyFields = this._getKeyFields();
        for (var i = 0; i < keyFields.length; i++) {
            var name = keyFields[i];
            if (name === 'sys_created_on' || name === 'sys_updated_on' ||
                name === 'sys_created_by' || name === 'sys_updated_by' ||
                name === 'sys_mod_count' || name === 'sys_id') {
                continue;
            }
            var val = gr.getValue(name);
            if (val !== null && val !== undefined) {
                fields[name] = val;
            }
        }
        var sortedKeys = Object.keys(fields).sort();
        var normalized = '';
        for (var j = 0; j < sortedKeys.length; j++) {
            normalized += sortedKeys[j] + '=' + fields[sortedKeys[j]] + '\n';
        }
        return normalized;
    },

    _sha256: function(input) {
        var digest = new GlideDigest();
        return digest.sha256_digest(input);
    },

    _summarizeFields: function(gr, artifactType) {
        var summary = {};
        var keyFields = this._getKeyFields();
        for (var i = 0; i < keyFields.length; i++) {
            var val = gr.getValue(keyFields[i]);
            if (val !== null && val !== undefined && val !== '') {
                summary[keyFields[i]] = val;
            }
        }
        return summary;
    },

    _getKeyFields: function() {
        var prop = gs.getProperty('x_csync.key_fields', '');
        if (prop) {
            return prop.split(',').map(function(f) { return f.trim(); });
        }
        return ['name', 'active', 'script', 'condition', 'order', 'type',
                'value', 'description', 'access', 'when', 'action_insert',
                'action_update', 'action_delete', 'operation', 'element',
                'mandatory', 'read_only', 'default_value', 'trigger_type',
                'next_action', 'reverse_if_false'];
    },

    _loadSnapshot: function(snapshotId) {
        var snap = new GlideRecord('x_csync_snapshot');
        if (!snap.get(snapshotId)) {
            return null;
        }
        var artifactsJson = snap.getValue('artifacts_json') || '[]';
        var artifacts = JSON.parse(artifactsJson);
        return {
            sys_id: snapshotId,
            name: snap.getValue('name') || '',
            instance: snap.getValue('instance') || '',
            artifacts: artifacts
        };
    },

    _buildArtifactMap: function(artifacts) {
        var map = {};
        for (var i = 0; i < artifacts.length; i++) {
            var a = artifacts[i];
            var key = a.type + '::' + (a.sys_id || a.name);
            map[key] = a;
        }
        return map;
    },

    _createDriftItem: function(baselineArtifact, targetArtifact, changeType, baselineId, targetId) {
        var artifact = baselineArtifact || targetArtifact;
        var diff = this.generateDiff(baselineArtifact, targetArtifact);
        var riskScore = this.calculateRiskScore({
            artifact_type: artifact.type,
            change_type: changeType
        });

        return {
            snapshot_baseline: baselineId,
            snapshot_target: targetId,
            artifact_type: artifact.type,
            artifact_name: artifact.name || '',
            artifact_sys_id: artifact.sys_id || '',
            risk_score: riskScore,
            change_type: changeType,
            diff_summary: JSON.stringify(diff),
            ai_analysis: '',
            remediation_status: 'pending',
            detected_at: new GlideDateTime().toString()
        };
    },

    _saveDriftItem: function(item) {
        try {
            var existing = new GlideRecord('x_csync_drift_item');
            existing.addQuery('snapshot_baseline', item.snapshot_baseline);
            existing.addQuery('snapshot_target', item.snapshot_target);
            existing.addQuery('artifact_type', item.artifact_type);
            existing.addQuery('artifact_name', item.artifact_name);
            existing.setLimit(1);
            existing.query();
            if (existing.next()) {
                return;
            }

            var di = new GlideRecord('x_csync_drift_item');
            di.initialize();
            di.setValue('snapshot_baseline', item.snapshot_baseline);
            di.setValue('snapshot_target', item.snapshot_target);
            di.setValue('artifact_type', item.artifact_type);
            di.setValue('artifact_name', item.artifact_name);
            di.setValue('artifact_sys_id', item.artifact_sys_id);
            di.setValue('risk_score', item.risk_score);
            di.setValue('change_type', item.change_type);
            di.setValue('diff_summary', item.diff_summary);
            di.setValue('ai_analysis', item.ai_analysis || '');
            di.setValue('remediation_status', item.remediation_status);
            di.setValue('detected_at', item.detected_at || '');
            di.setWorkflow(false);
            di.insert();
        } catch (e) {
            gs.error('ConfigSyncEngine._saveDriftItem failed: ' + e.message);
        }
    },

    _countDriftItems: function(snapshotId) {
        var di = new GlideRecord('x_csync_drift_item');
        di.addQuery('snapshot_baseline', snapshotId);
        di.addOrCondition('snapshot_target', snapshotId);
        di.query();
        return di.getRowCount();
    },

    type: 'ConfigSyncEngine'
};
